head.script:

	scwin.onpageload = function() {
		var jsonData = [{col1:"a",col2:"a1",col3:"1000", col4:"a"}
						,{col1:"a",col2:"a2",col3:"1000", col4:"a"}
						,{col1:"a",col2:"a3",col3:"1000", col4:"a"}
						,{col1:"a",col2:"a4",col3:"1000", col4:"a"}
						,{col1:"a",col2:"a5",col3:"1000", col4:"a"}
						,{col1:"b",col2:"b1",col3:"1000", col4:"b"}
						,{col1:"b",col2:"b3",col3:"1000", col4:"b"}
						,{col1:"c",col2:"c1",col3:"1000", col4:"c"}
						,{col1:"c",col2:"c2",col3:"1000", col4:"c"}
						,{col1:"c",col2:"c3",col3:"1000", col4:"c"}
						,{col1:"d",col2:"d1",col3:"1000", col4:"d"}
						,{col1:"d",col2:"d2",col3:"1000", col4:"d"}
						,{col1:"d",col2:"d3",col3:"1000", col4:"d"}];
		dataList1.setJSON(jsonData);
	};

	scwin.onpageunload = function() {

	};
	scwin.summaryFormatFunction = function(data){
		var retdata = "";
		debugger;
		var tempArr = data.split(",");
		if(tempArr[1] == 1){
			retdata = " " + tempArr[0] + " Summary";
		}else{
			retdata =  " " + tempArr[0] + " " + tempArr[1] + ' [ ' + tempArr[2] + ' 건 ] ' 
		}

		return retdata;
	};

	scwin.testFormatFunction = function(data){
		return data + "원";
	};

	scwin.trigger1_onclick = function(e) {
		var options = {};
		options.closeGroup = true;
		options.sortIndex = [4];	//sort될 column index
   		options.sortOrder = [1];	//1로 설정되면 오름차순 정렬, -1로 설정되면 내림차순 정렬
		options.groupbyHeader = [{colSpan: "5", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
		options.groupbyFooter = [
				{colSpan:"5",inputType: "expression", expression: " SUM('col3')", displayFormatter: "scwin.countFormatFunction", align: "center"}
		];
		options.hideFooter = true;
		gridView1.groupby( options ); //그룹핑 시작
	};
	scwin.trigger2_onclick = function(e) {
		gridView1.clearGroupby();
	};
	scwin.gridView1_ongroupby = function(options) {
				scwin.groupby_test(options);
			};
			scwin.groupby_test = function(options){
				debugger;
				var flag = true;
				if(flag) {
					options.closeGroup = true; 

					options.groupbyHeader = [{colSpan: "5", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
					options.groupbyFooter = [
						{colSpan:"5",inputType: "expression", expression: " SUM('col3')", displayFormatter: "scwin.countFormatFunction", align: "center"}
					];

					debugger;
					gridView1.groupby( options ); //실제 groupby 실행

				} else {
					return false; 
				}
			};



			scwin.gridView1_onviewchange = function(info){
				if(info.colIndex == 0){
debugger;
					if(info.newValue == 1){
						dataList1.setCellData(info.rowIndex, "col4", "1")
						gridView1.clearGroupby();
						var options = {};
						options.closeGroup = false;
						options.sortIndex = [4];	//sort될 column index
				   		options.sortOrder = [1];	//1로 설정되면 오름차순 정렬, -1로 설정되면 내림차순 정렬
						options.groupbyHeader = [{colSpan: "5", inputType: "expression", expression: " toggle() + ',' +  depthStr() + ',' + count() ", displayFormatter: "scwin.summaryFormatFunction", align: "left" }];
						options.groupbyFooter = [
								{colSpan:"5",inputType: "expression", expression: " SUM('col3')", displayFormatter: "scwin.testFormatFunction", align: "center"}
						];
						options.hideFooter = true;
						gridView1.groupby( options ); //그룹핑 시작
					}
				}

			}

		scwin.checkVal = function() {
			return WebSquare.wUnit.getDomById('gridView1_cell_1_1').style.backgroundColor == '';
		}	

		scwin.unitTest = function(){
			//init
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");		
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
			WebSquare.wUnit.addCommand("pause", "500");	
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').querySelector('span').click()");
			WebSquare.wUnit.addCommand("pause", "500");	
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_1_1').click()");
			WebSquare.wUnit.addCommand("pause", "500");	
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
			WebSquare.wUnit.addCommand("pause", "500");		
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
			WebSquare.wUnit.addCommand("pause", "500");		

			//Run  and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}
		scwin.unitTest();
